  const orient = pts => { let a = 0; for (let q = 0; q < pts.length; q++) { const p = pts[q], r = pts[(q + 1) % pts.length]; a += p[0] * r[1] - r[0] * p[1]; } return Math.sign(a) === dir ? pts : pts.slice().reverse(); };
