        const gx = dEdge[c + 1] - dEdge[c - 1], gy = dEdge[c + GW] - dEdge[c - GW], gl = Math.hypot(gx, gy) || 1;
        nx = p.x + gx / gl * 0.4; ny = p.y + gy / gl * 0.4;
